{"code":"import os, urllib.request, json

# Test the FreelLM endpoint for Gemini models
url = 'http://124.107.126.226:3001/v1/models'
try:
    req = urllib.request.Request(url)
    resp = urllib.request.urlopen(req, timeout=15)
    data = json.loads(resp.read())
    models = [m for m in data.get('data', []) if 'gemini' in m.get('id', '').lower()]
    print(f'FreelLM Gemini models available: {len(models)}')
    for model in models[:5]:
        print(f'  - {model.get("id", "Unknown")}')
except Exception as e:
    print(f'FreelLM API error: {e}')"}

